46-export const CLAUDE_MD = 'CLAUDE.md';
47-export const README = 'README.md';
48-
49-// The pack-badge row: the marks of the packs this repo declares, on a single
50-// line of its README. Adoption seeds it and the repo owns it from there — which
51-// is why the row is gated behind `{ badges: true }` (the CLI's `--badges`, passed
52-// by bootstrap alone) rather than converged like the surfaces around it. A
53-// README belongs to its repo: a nightly that re-derived this row would rewrite a
54-// member's README every time its declaration moved, so the nightly stays out and
55-// a stale row is the repo's to fix (re-run the converge with `--badges`).
56-//
57-// Delimited by HTML comments rather than located by position, so the row can be
58-// re-converged in place wherever the repo has moved it, and so anything the repo
59-// writes AFTER the closing marker on the same line (a tagline, a build badge) is
60-// its own and survives untouched — which is why the CLOSING marker stays inline,
61-// at the end of the badges' own line.
62-//
63-// The OPENING marker gets a line to itself, and that newline is load-bearing: a
64-// line that BEGINS with `<!--` opens a CommonMark HTML block, and every character
65-// through the line carrying `-->` is then emitted as raw HTML. Put the badges
66-// after the opening marker on one line and a README renders the literal text
67-// `![basics](…)` instead of the images (#587). Breaking the line ends the HTML
68-// block at the marker, so the badges start a paragraph and parse as markdown.
69-export const BADGE_ROW_START = '<!-- claudinite:packs -->';
70-export const BADGE_ROW_END = '<!-- /claudinite:packs -->';
71-const BADGE_ROW_RE = new RegExp(`${BADGE_ROW_START}[\\s\\S]*?${BADGE_ROW_END}`);
72-
73-// The retired corpus-index import (#385): a line importing `.claudinite/shared/CLAUDE.md`.
74-// The whole line (and its trailing newline) is removed wherever it appears.
75-const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;
76-
77-// The project's settings, loaded through the one reader that validates them.
78-// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
--
112:  for (const h of REQUIRED_HOOKS) {
113-    const list = (settings.hooks[h.event] ??= []);
114-    const ours = (group) => (group.hooks ?? []).some((entry) => entry?.command === h.command);
115-    const present = list.some((group) => (h.matcher == null || group.matcher === h.matcher) && ours(group));
116-    // The command is the registration's identity: a group already running it under
117-    // an earlier matcher is retargeted, never joined by a second group that would
