const fs = require('fs');
// repo-context: the change's removed lines, and the untracked file set
{
  const f = 'engine/checks/helpers/repo-context.mjs';
  let t = fs.readFileSync(f, 'utf8');
  const a1 = '    tracked,\n    deleted,\n';
  if (!t.includes(a1)) throw new Error('ctx list anchor missing');
  t = t.replace(a1, '    tracked,\n    untracked,\n    deleted,\n');
  const a2 = `    conversation() {`;
  if (!t.includes(a2)) throw new Error('conversation anchor missing');
  t = t.replace(a2, `    // The lines the change REMOVES from a tracked file, numbered as the base
    // had them — the diff's "-" side, the mirror of addedLines. A file the
    // base did not hold removed nothing.
    removedLines(file) {
      if (!mergeBase || !tracked.includes(file)) return [];
      const out = gitTry(root, 'diff', '-U0', diffBase, '--', file);
      const removed = [];
      let lineNo = 0;
      for (const l of (out || '').split('\\n')) {
        const hunk = /^@@ -(\\d+)(?:,\\d+)? \\+\\d+(?:,\\d+)? @@/.exec(l);
        if (hunk) { lineNo = Number(hunk[1]); continue; }
        if (l.startsWith('-') && !l.startsWith('---')) { removed.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
        else if (!l.startsWith('+')) lineNo += l ? 1 : 0;
      }
      return removed;
    },

    conversation() {`);
  fs.writeFileSync(f, t);
  console.log('repo-context edited');
}
// work.mjs: the fluent surface over them
{
  const f = 'engine/checks/helpers/work.mjs';
  let t = fs.readFileSync(f, 'utf8');
  const a1 = '  get tracked() { return this.ctx.tracked; }\n';
  if (!t.includes(a1)) throw new Error('tracked getter anchor missing');
  t = t.replace(a1, a1 + '  // The run\'s files git does not track — the new test a green run never executed.\n  get untracked() { return this.ctx.untracked ?? []; }\n');
  const a2 = '  addedLines(files) { return addedLines(this.ctx, files ?? this.ctx.changedFiles); }\n';
  if (!t.includes(a2)) throw new Error('addedLines anchor missing');
  t = t.replace(a2, a2 + `
  // The change's removed lines across \`files\` (default: every changed file):
  // [{ file, line, text }], line as the base numbered it.
  removedLines(files) {
    const out = [];
    if (typeof this.ctx.removedLines !== 'function') return out;
    for (const file of files ?? this.ctx.changedFiles) {
      for (const { line, text } of this.ctx.removedLines(file)) out.push({ file, line, text });
    }
    return out;
  }

  // Every comment class the session's replies declared, across all owner turns
  // — the set a work rule gates itself on. Empty without a transcript.
  replyClasses() {
    const classes = new Set();
    for (const turn of this.conversation().ownerTurns()) for (const c of turn.classes()) classes.add(c);
    return classes;
  }
`);
  fs.writeFileSync(f, t);
  console.log('work.mjs edited');
}
EOF
