1	#!/usr/bin/env node
2	// Claude Code PreToolUse guard, three duties, in this order:
3	//  - a file tool (Edit, Write, NotebookEdit) aimed at a path one of an active
4	//    pack's skills names under `force-load-on-file-edits-paths` is blocked until
5	//    the session has loaded that skill — so the skill is read before the first
6	//    edit exists, not after a Stop-time finding has sent the agent back over
7	//    work done;
8	//  - the active packs' ACTION declarations (`scope: "action"`, `guardToolCalls` —
9	//    the vocabulary in engine/checks/helpers/pattern-rules.mjs) are judged
10	//    against the call about to run: a blocking finding denies it and hands the
11	//    agent the finding's text, an advisory one lets it run and injects the text
12	//    as context, so a bias is heard at the moment it applies. The same
13	//    declarations run again over the transcript at Stop, the backstop for a
14	//    hook that never fired;
15	//  - a Bash command that deletes a remote branch is blocked (the delete-push
16	//    fails in this environment, so it can never succeed).
17	// Exit 2 blocks the tool call and feeds stderr back to the agent; exit 0 with a
18	// JSON `hookSpecificOutput` on stdout allows it with added context. Registered
19	// per-repo on every tool (the converge's PRETOOLUSE_MATCHER) — see bootstrap.md; a
20	// call no declaration names costs the pack load, about 150 ms, and says nothing.
21	// A guard that cannot decide lets the call through: an unreadable declaration or
22	// registry is the mount self-test's finding, never a session wedged on tools.
23	import { existsSync, readFileSync } from 'node:fs';
24	import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
25	import { fileURLToPath } from 'node:url';
26	import { hooklog } from '../checks/helpers/hook-log.mjs';
27	import { applyGrace } from '../checks/helpers/findings.mjs';
28	import { parseEntries, skillLoads, toolCalls } from '../checks/helpers/session-transcript.mjs';
29	import { guardFindings } from '../checks/helpers/pattern-rules.mjs';
30	import { packRules } from '../checks/run-active-pack-rules.mjs';
31	import { pathScopedSkills, missingSkillsFor } from '../pack_loader/path-scoped-skills.mjs';
32	import { settingsPath } from '../settings-file.mjs';
33	
34	// This module lives at <corpus>/engine/hooks/ — the same root the mount hook
35	// resolves the registry from, so the canon runs it from its own tree.
36	const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
37	
38	// The file a tool is about to write, repo-relative with forward slashes — or null
39	// when the tool names no file or the file is outside the project (nothing here
40	// scopes a path the repo does not own).
41	function targetPath(payload, projectRoot) {
42	  const input = payload.tool_input ?? {};
43	  const raw = payload.tool_name === 'NotebookEdit' ? input.notebook_path : input.file_path;
44	  if (typeof raw !== 'string' || !raw) return null;
45	  const abs = isAbsolute(raw) ? raw : resolve(projectRoot, raw);
46	  const rel = relative(projectRoot, abs);
47	  if (!rel || rel.startsWith('..') || isAbsolute(rel)) return null;
48	  return rel.split(sep).join('/');
49	}
50	
51	// The raw settings, read once: the declared packs (what activates) and the
52	// per-rule overrides (off / advisory / blocking), project-wide and per pack entry.
53	function readSettings(projectRoot) {
54	  const path = settingsPath(projectRoot);
55	  if (!existsSync(path)) return { packs: [], rules: {} };
56	  const raw = JSON.parse(readFileSync(path, 'utf8'));
57	  const rules = { ...(raw.rules ?? {}) };
58	  for (const entry of Array.isArray(raw.packs) ? raw.packs : []) {
59	    if (entry && typeof entry === 'object') Object.assign(rules, entry.rules ?? {});
60	  }
61	  return { packs: Array.isArray(raw.packs) ? raw.packs : [], rules };
62	}
63	
64	async function activePacks(projectRoot, declared) {
65	  const { loadPacks, isActive } = await import(join(corpusRoot, 'engine', 'pack_loader', 'pack-registry.mjs'));
66	  const packs = await loadPacks({ localRoot: projectRoot });
67	  return packs.filter((p) => isActive(p, { packs: declared }));
68	}
69	
70	function transcriptEntries(transcriptPath) {
71	  if (!transcriptPath || !existsSync(transcriptPath)) return [];
72	  try { return parseEntries(readFileSync(transcriptPath, 'utf8')); } catch { return []; }
73	}
74	
75	const FILE_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit']);
76	
77	function guardFileTool(payload, projectRoot, packs) {
78	  const path = targetPath(payload, projectRoot);
79	  if (!path) return;
80	  const declarations = pathScopedSkills(packs);
81	  if (!declarations.length) return;
82	  const missing = missingSkillsFor(path, declarations, skillLoads(transcriptEntries(payload.transcript_path)));
83	  if (!missing.length) return;
84	  const names = missing.map((d) => d.skill);
85	  hooklog('PreToolUse', `done exit=2 skill-not-loaded ${path} needs ${names.join(',')}`);
86	  // Reading the skill's own file is a load too (the transcript reader counts it), so
87	  // the message carries that path beside the Skill call.
88	  const skillFile = (d) => relative(projectRoot, join(d.dir, 'SKILL.md')).split(sep).join('/');
89	  process.stderr.write(
90	    `Blocked: ${path} is edited only with the ${names.map((n) => `\`${n}\``).join(' and ')} skill loaded `
91	    + `(the ${[...new Set(missing.map((d) => d.pack))].join(', ')} pack's skill forces itself for ${missing.map((d) => d.files).join(', ')}). `
92	    + `Load it first — Skill tool, ${names.map((n) => `skill: "${n}"`).join(', ')}, or Read ${missing.map(skillFile).join(' or ')} — then retry the edit.`,
93	  );
94	  process.exit(2);
95	}
96	
97	// The action declarations judged against this call. Blocking findings deny
98	// (exit 2); advisory ones come back as the context to inject. Grace applies as
99	// at Stop: a blocking guard inside its `since` window advises.
100	function guardAction(payload, packs, overrides) {
101	  const rules = packRules(packs).filter((r) => r.scope === 'action' && overrides[r.id] !== 'off');
102	  if (!rules.length) return '';
103	  const call = { name: payload.tool_name, input: payload.tool_input ?? {} };
104	  let prior = null;
105	  const priorCalls = () => (prior ??= toolCalls(transcriptEntries(payload.transcript_path)));
106	  let findings = [];
107	  for (const rule of rules) {
108	    const countsCalls = (rule.spec?.guardToolCalls ?? []).some((a) => a.atMostPerSession !== undefined);
109	    let found;
110	    try { found = guardFindings(rule, call, countsCalls ? priorCalls() : []); }
111	    catch (e) { hooklog('PreToolUse', `action-guard-failed ${rule.id} ${e?.message ?? e}`); continue; }
112	    const level = overrides[rule.id];
113	    findings.push(...found.map((f) => (level === 'advisory' || level === 'blocking' ? { ...f, severity: level } : f)));
114	  }
115	  findings = applyGrace(findings);
116	  const render = (f) => `${f.what}. ${f.why ? `${f.why}. ` : ''}Fix: ${f.fix}`;
117	  const blocking = findings.filter((f) => f.severity === 'blocking');
118	  if (blocking.length) {
119	    hooklog('PreToolUse', `done exit=2 action-guard ${blocking.map((f) => f.rule).join(',')}`);
120	    process.stderr.write(blocking.map((f) => `Blocked by ${f.rule}: ${render(f)}`).join('\n'));
121	    process.exit(2);
122	  }
123	  const advisory = findings.filter((f) => f.severity === 'advisory');
124	  if (!advisory.length) return '';
125	  hooklog('PreToolUse', `advisory action-guard ${advisory.map((f) => f.rule).join(',')}`);
126	  return advisory.map((f) => `[claudinite ${f.rule}] ${render(f)}`).join('\n');
127	}
128	
129	function guardRemoteBranchDelete(payload) {
130	  const cmd = payload.tool_input?.command ?? '';
131	  const deletesRemoteBranch =
132	    /\bgit\s+push\b[^\n;&]*\s(--delete|-d)\s/.test(cmd) ||
133	    /\bgit\s+push\b[^\n;&]*\s\S+\s+:\S/.test(cmd);
134	  if (!deletesRemoteBranch) return;
135	  // Log only the block — the interesting event. An allowed command every Bash
136	  // call would flood the log and drown the SessionStart signal it exists for.

