const fs = require('fs');
const edit = (file, pairs) => { let t = fs.readFileSync(file, 'utf8'); for (const [from, to] of pairs) { if (!t.includes(from)) throw new Error(`${file}: anchor missing: ${from.slice(0, 60)}`); t = t.replace(from, to); } fs.writeFileSync(file, t); console.log('edited', file); };

// --- skill-frontmatter: the three trigger keys beside the path key ---
edit('engine/pack_loader/skill-frontmatter.mjs', [
  [`export const FORCE_LOAD_KEY = 'force-load-on-file-edits-paths';`,
   `export const FORCE_LOAD_KEY = 'force-load-on-file-edits-paths';
// The other three moments a skill may force itself for, under \`metadata\` too:
// a tool call, an owner prompt, a tool result. An entry is one scalar — single-
// quote it in the frontmatter, since a regex carries backslashes:
//   force-load-on-tool-calls:          - 'mcp__github__create_pull_request'
//                                      - 'Bash /(^|[;&|]\\\\s*)git\\\\s+commit\\\\b/'
//   force-load-on-prompts-matching:    - '/\\\\bLGTM\\\\b/'
//   force-load-on-tool-results-matching: - 'WebFetch /EGRESS_BLOCKED|\\\\b403\\\\b/'
// A tool entry is the tool's exact name or a /regex/ over names, then optionally
// a space and a /regex/ over the call's input (or its result) serialized as JSON.
export const TOOL_CALL_KEY = 'force-load-on-tool-calls';
export const PROMPT_KEY = 'force-load-on-prompts-matching';
export const TOOL_RESULT_KEY = 'force-load-on-tool-results-matching';

const RE_FORM = /^\\/(.*)\\/([a-z]*)$/s;
const toRegExp = (s) => { const m = RE_FORM.exec(String(s).trim()); try { return m ? new RegExp(m[1], m[2]) : null; } catch { return null; } };
const listAt = (fm, key) => {
  const v = fm?.metadata && typeof fm.metadata === 'object' && !Array.isArray(fm.metadata) ? fm.metadata[key] : undefined;
  return Array.isArray(v) ? v : typeof v === 'string' && v.trim() ? [v] : [];
};

// "<tool>" or "<tool> /regex/" → { tool (name or RegExp), pattern (RegExp or
// null), source }; a malformed entry is null (dropped, never a wedged hook).
export function parseToolTrigger(entry) {
  const m = /^(\\/(?:[^/\\\\]|\\\\.)*\\/[a-z]*|[^\\s/][^\\s]*)(?:\\s+(\\/.*\\/[a-z]*))?$/s.exec(String(entry).trim());
  if (!m) return null;
  const tool = m[1].startsWith('/') ? toRegExp(m[1]) : m[1];
  if (tool === null) return null;
  const pattern = m[2] ? toRegExp(m[2]) : null;
  if (m[2] && !pattern) return null;
  return { tool, pattern, source: String(entry).trim() };
}
export const toolCallTriggersOf = (fm) => listAt(fm, TOOL_CALL_KEY).map(parseToolTrigger).filter(Boolean);
export const toolResultTriggersOf = (fm) => listAt(fm, TOOL_RESULT_KEY).map(parseToolTrigger).filter(Boolean);
export const promptTriggersOf = (fm) => listAt(fm, PROMPT_KEY)
  .map((s) => ({ re: toRegExp(s), source: String(s).trim() })).filter((p) => p.re);`],
  [`// The metadata of the skill at \`dir\`: { name, description, forceLoadPaths }.`,
   `// The metadata of the skill at \`dir\`: { name, description, forceLoadPaths,
// toolCallTriggers, promptTriggers, toolResultTriggers }.`],
  [`    forceLoadPaths: forceLoadPathsOf(fm),
  };`,
   `    forceLoadPaths: forceLoadPathsOf(fm),
    toolCallTriggers: toolCallTriggersOf(fm),
    promptTriggers: promptTriggersOf(fm),
    toolResultTriggers: toolResultTriggersOf(fm),
  };`],
]);

// --- path-scoped-skills: the other three selectors beside the path one ---
edit('engine/pack_loader/path-scoped-skills.mjs', [
  [`// The declarations \`path\` matches whose skill is not among \`loaded\`, deduped by
// skill name — the reason to stop an edit, or the empty list that lets it run.
export function missingSkillsFor(path, declarations, loaded) {
  const have = new Set(loaded ?? []);
  const seen = new Set();
  const missing = [];
  for (const d of declarations) {
    if (!d.re.test(path) || have.has(d.skill) || seen.has(d.skill)) continue;
    seen.add(d.skill);
    missing.push(d);
  }
  return missing;
}`,
   `// The declarations \`hit\` admits whose skill is not among \`loaded\`, deduped by
// skill name — the reason to stop an action, or the empty list that lets it run.
function missing(declarations, loaded, hit) {
  const have = new Set(loaded ?? []);
  const seen = new Set();
  const out = [];
  for (const d of declarations) {
    if (!hit(d) || have.has(d.skill) || seen.has(d.skill)) continue;
    seen.add(d.skill);
    out.push(d);
  }
  return out;
}

export const missingSkillsFor = (path, declarations, loaded) => missing(declarations, loaded, (d) => d.re.test(path));

// The TRIGGERED skills of the given packs, the three moments beside the path
// one: [{ pack, skill, dir, kind: 'toolCall' | 'prompt' | 'toolResult', tool,
// pattern, source }], one entry per trigger, read off the same skill metadata.
export function triggeredSkills(packs) {
  const out = [];
  for (const pack of packs ?? []) {
    if (!pack.dir) continue;
    for (const skill of pack.skills ?? []) {
      const dir = join(pack.dir, 'skills', skill);
      const meta = skillMetadata(dir);
      for (const t of meta.toolCallTriggers ?? []) out.push({ pack: pack.id, skill, dir, kind: 'toolCall', tool: t.tool, pattern: t.pattern, source: t.source });
      for (const p of meta.promptTriggers ?? []) out.push({ pack: pack.id, skill, dir, kind: 'prompt', tool: null, pattern: p.re, source: p.source });
      for (const t of meta.toolResultTriggers ?? []) out.push({ pack: pack.id, skill, dir, kind: 'toolResult', tool: t.tool, pattern: t.pattern, source: t.source });
    }
  }
  return out;
}

const namesTool = (d, name) => (d.tool instanceof RegExp ? d.tool.test(name) : d.tool === name);
const asText = (v) => (typeof v === 'string' ? v : JSON.stringify(v ?? {}));

// A call ({ name, input }) about to run, or recorded: the tool-call triggers it
// hits whose skill the session has not loaded.
export const missingSkillsForCall = (call, declarations, loaded) => missing(declarations, loaded,
  (d) => d.kind === 'toolCall' && namesTool(d, call.name) && (!d.pattern || d.pattern.test(asText(call.input))));

// An owner prompt: the prompt triggers its text hits.
export const missingSkillsForPrompt = (text, declarations, loaded) => missing(declarations, loaded,
  (d) => d.kind === 'prompt' && d.pattern.test(text ?? ''));

// A call's result: the result triggers it hits.
export const missingSkillsForResult = (call, output, declarations, loaded) => missing(declarations, loaded,
  (d) => d.kind === 'toolResult' && namesTool(d, call.name) && d.pattern.test(asText(output)));`],
]);
