  const m = /^(\\/(?:[^/\\\\]|\\\\.)*\\/[a-z]*|[^\\s/][^\\s]*)(?:\\s+(\\/.*\\/[a-z]*))?$/s.exec(String(entry).trim());
  if (!m) return null;
  const tool = m[1].startsWith('/') ? toRegExp(m[1]) : m[1];
  if (tool === null) return null;
  const pattern = m[2] ? toRegExp(m[2]) : null;
