// What every guarding hook reads before it can judge anything: the project's
// declared packs and rule overrides, the active pack objects, and the session
// transcript. One reader, so the PreToolUse, UserPromptSubmit and PostToolUse
// commands cannot disagree about which packs are active or which skills the
// session has loaded.
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseEntries, skillLoads } from '../checks/helpers/session-transcript.mjs';
import { settingsPath } from '../settings-file.mjs';

// This module lives at <corpus>/engine/hooks/ — the same root the mount hook
// resolves the registry from, so the canon runs it from its own tree.
export const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));

// The raw settings: the declared packs (what activates) and the per-rule
// overrides (off / advisory / blocking), project-wide and per pack entry.
export function readSettings(projectRoot) {
  const path = settingsPath(projectRoot);
  if (!existsSync(path)) return { packs: [], rules: {} };
  const raw = JSON.parse(readFileSync(path, 'utf8'));
  const rules = { ...(raw.rules ?? {}) };
  for (const entry of Array.isArray(raw.packs) ? raw.packs : []) {
    if (entry && typeof entry === 'object') Object.assign(rules, entry.rules ?? {});
  }
  return { packs: Array.isArray(raw.packs) ? raw.packs : [], rules };
}

export async function activePacks(projectRoot, declared) {
  const { loadPacks, isActive } = await import(join(corpusRoot, 'engine', 'pack_loader', 'pack-registry.mjs'));
  const packs = await loadPacks({ localRoot: projectRoot });
  return packs.filter((p) => isActive(p, { packs: declared }));
}

export function transcriptEntries(transcriptPath) {
  if (!transcriptPath || !existsSync(transcriptPath)) return [];
  try { return parseEntries(readFileSync(transcriptPath, 'utf8')); } catch { return []; }
}

export const loadedSkills = (transcriptPath) => skillLoads(transcriptEntries(transcriptPath));

// The one sentence every trigger's block or nudge ends with: how to load the
// skill. Reading the skill's own file is a load too (the transcript reader
// counts it), so the message carries that path beside the Skill call.
export function loadInstruction(missing, projectRoot) {
  const rel = (d) => join(d.dir, 'SKILL.md').replace(`${projectRoot}/`, '').split('\\').join('/');
  return `Skill tool, ${missing.map((d) => `skill: "${d.skill}"`).join(', ')}, or Read ${missing.map(rel).join(' or ')}`;
}

#!/usr/bin/env node
// Claude Code UserPromptSubmit hook: an owner prompt a skill forces itself for
// (`force-load-on-prompts-matching` in the skill's metadata —
// engine/pack_loader/path-scoped-skills.mjs) gets the load instruction injected
// beside the prompt, so the procedure the phrase names ("LGTM", "/do-later")
// is in front of the session before it acts. Once per session: a skill already
// loaded is never asked for again. Never blocks, and a hook that cannot decide
// says nothing — an unreadable registry is the mount self-test's finding.
import { hooklog } from '../checks/helpers/hook-log.mjs';
import { triggeredSkills, missingSkillsForPrompt } from '../pack_loader/path-scoped-skills.mjs';
import { readSettings, activePacks, loadedSkills, loadInstruction } from './hook-context.mjs';

async function main(payload) {
  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  const prompt = typeof payload.prompt === 'string' ? payload.prompt : '';
  if (!prompt.trim()) return;
  const packs = await activePacks(projectRoot, readSettings(projectRoot).packs);
  const declarations = triggeredSkills(packs).filter((d) => d.kind === 'prompt');
  if (!declarations.length) return;
  const missing = missingSkillsForPrompt(prompt, declarations, loadedSkills(payload.transcript_path));
  if (!missing.length) return;
  hooklog('UserPromptSubmit', `skill-trigger ${missing.map((d) => d.skill).join(',')}`);
  const lines = missing.map((d) =>
    `Claudinite: this prompt matches the \`${d.skill}\` skill's trigger (${d.source}, the ${d.pack} pack) — load it before acting on the prompt: ${loadInstruction([d], projectRoot)}.`);
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: { hookEventName: 'UserPromptSubmit', additionalContext: lines.join('\n') },
  }));
}

let input = '';
process.stdin.on('data', (d) => { input += d; });
process.stdin.on('end', () => {
  let payload = {};
  try { payload = JSON.parse(input); } catch { /* no payload → nothing to say */ }
  main(payload).then(() => process.exit(0), (e) => {
    hooklog('UserPromptSubmit', `done exit=0 trigger-failed ${e?.message ?? e}`);
    process.exit(0);
  });
});

#!/usr/bin/env node
// Claude Code PostToolUse hook: a tool result a skill forces itself for
// (`force-load-on-tool-results-matching` in the skill's metadata —
// engine/pack_loader/path-scoped-skills.mjs) gets the load instruction injected
// beside the result, so the diagnosis a symptom calls for (a proxy denial, a
// missing module) is in front of the session the moment the symptom appears.
// Once per session: a skill already loaded is never asked for again. Never
// blocks; a hook that cannot decide says nothing.
import { hooklog } from '../checks/helpers/hook-log.mjs';
import { triggeredSkills, missingSkillsForResult } from '../pack_loader/path-scoped-skills.mjs';
import { readSettings, activePacks, loadedSkills, loadInstruction } from './hook-context.mjs';

async function main(payload) {
  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  if (typeof payload.tool_name !== 'string') return;
  const packs = await activePacks(projectRoot, readSettings(projectRoot).packs);
  const declarations = triggeredSkills(packs).filter((d) => d.kind === 'toolResult');
  if (!declarations.length) return;
  const call = { name: payload.tool_name, input: payload.tool_input ?? {} };
  const missing = missingSkillsForResult(call, payload.tool_response, declarations, loadedSkills(payload.transcript_path));
  if (!missing.length) return;
  hooklog('PostToolUse', `skill-trigger ${payload.tool_name} ${missing.map((d) => d.skill).join(',')}`);
  const lines = missing.map((d) =>
    `Claudinite: this ${payload.tool_name} result matches the \`${d.skill}\` skill's trigger (${d.source}, the ${d.pack} pack) — load it before acting on the result: ${loadInstruction([d], projectRoot)}.`);
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: lines.join('\n') },
  }));
}

let input = '';
process.stdin.on('data', (d) => { input += d; });
process.stdin.on('end', () => {
  let payload = {};
  try { payload = JSON.parse(input); } catch { /* no payload → nothing to say */ }
  main(payload).then(() => process.exit(0), (e) => {
    hooklog('PostToolUse', `done exit=0 trigger-failed ${e?.message ?? e}`);
    process.exit(0);
  });
});

