// The tool-call triggers: a call a skill forces itself for is held until the
// skill is loaded, exactly as an edit under a scoped path is.
function guardToolCallTrigger(payload, projectRoot, packs) {
  const declarations = triggeredSkills(packs).filter((d) => d.kind === 'toolCall');
  if (!declarations.length) return;
  const call = { name: payload.tool_name, input: payload.tool_input ?? {} };
  const missing = missingSkillsForCall(call, declarations, skillLoads(transcriptEntries(payload.transcript_path)));
  if (!missing.length) return;
  const names = missing.map((d) => d.skill);
  hooklog('PreToolUse', `done exit=2 skill-not-loaded-for-call ${payload.tool_name} needs ${names.join(',')}`);
  process.stderr.write(
    `Blocked: ${payload.tool_name} is called only with the ${names.map((n) => `\`${n}\``).join(' and ')} skill loaded `
    + `(the ${[...new Set(missing.map((d) => d.pack))].join(', ')} pack's skill forces itself for ${missing.map((d) => d.source).join(', ')}). `
    + `Load it first — ${loadInstruction(missing, projectRoot)} — then retry the call.`,
